"""Writes the generated files windows/build.bat compiles: the Tugmali tables, typing cases and version.

Run from the repo root: python3 -m uzkbd.windows.build
"""

from __future__ import annotations

import plistlib
from pathlib import Path

from uzkbd.windows.c_writer import HEADER, to_cases_h, to_chars_h
from uzkbd.windows.tugmali import build_tugmali

ROOT = Path(__file__).resolve().parents[2]


def app_version() -> str:
    # The Mac app's version is the release version; the Windows DLL and installer carry the same one.
    with open(ROOT / "app" / "Info.plist", "rb") as plist:
        return plistlib.load(plist)["CFBundleShortVersionString"]


def version_h(version: str) -> str:
    parts = ",".join((version.split(".") + ["0"] * 4)[:4])
    return f'{HEADER}#define XATTOT_VERSION {parts}\n#define XATTOT_VERSION_STR "{version}"\n'


def version_iss(version: str) -> str:
    return f'; Generated by uzkbd/windows/build.py. Do not edit.\n#define Version "{version}"\n'


def main() -> None:
    out = ROOT / "dist" / "windows" / "gen"
    out.mkdir(parents=True, exist_ok=True)
    layout = build_tugmali()
    version = app_version()
    (out / "chars.h").write_text(to_chars_h(layout), encoding="ascii")
    (out / "cases.h").write_text(to_cases_h(layout), encoding="ascii")
    (out / "version.h").write_text(version_h(version), encoding="ascii")
    (out / "version.iss").write_text(version_iss(version), encoding="ascii")
    print(out)


if __name__ == "__main__":
    main()
